long long min_ops(long long *a, int n, int start_sign) {
    long long prefix = 0, ops = 0;
    int sign = start_sign; // 1 for positive, -1 for negative
    for (int i = 0; i < n; i++) {
        prefix += a[i];
        if (prefix * sign <= 0) {
            long long needed = (sign == 1) ? 1 : -1;
            long long diff = labs(needed - prefix);
            ops += diff;
            prefix = needed;
        }
        sign = -sign;
    }
    return ops;
}

