typedef long long ll;

static ll absll(ll x) {
    return x >= 0 ? x : -x;
}

/*
  Compute minimum operations if prefix sums must alternate signs,
  starting with:
    startPositive = 1 : s1 > 0, s2 < 0, s3 > 0, ...
    startPositive = 0 : s1 < 0, s2 > 0, s3 < 0, ...
*/
static ll solve_pattern(ll *a, int n, int startPositive) {
    ll cost = 0;
    ll sum = 0;

    for (int i = 0; i < n; i++) {
        sum += a[i];

        int shouldBePositive = ((i % 2) == 0) ? startPositive : !startPositive;

        if (shouldBePositive) {
            if (sum <= 0) {
                ll need = 1 - sum;   // increase current element by need
                cost += need;
                sum = 1;
            }
        } else {
            if (sum >= 0) {
                ll need = sum + 1;   // decrease current element by need
                cost += need;
                sum = -1;
            }
        }
    }

    return cost;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    ll *a = (ll *)malloc(sizeof(ll) * n);
    for (int i = 0; i < n; i++) scanf("%lld", &a[i]);

    ll ans1 = solve_pattern(a, n, 1);
    ll ans2 = solve_pattern(a, n, 0);

    printf("%lld\n", ans1 < ans2 ? ans1 : ans2);

    free(a);
    return 0;
}

