import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) {
            a[i] = sc.nextLong();
        }

        long ans = Long.MAX_VALUE;

        // Try two patterns
        for (int startSign = 1; startSign >= -1; startSign -= 2) {
            long currentSum = 0;
            long operations = 0;
            int sign = startSign;

            for (int i = 0; i < n; i++) {
                currentSum += a[i];
                if (sign > 0) {
                    // Need currentSum >= 1
                    if (currentSum <= 0) {
                        long diff = 1 - currentSum;
                        operations += diff;
                        currentSum = 1;
                    }
                } else {
                    // Need currentSum <= -1
                    if (currentSum >= 0) {
                        long diff = currentSum + 1;
                        operations += diff;
                        currentSum = -1;
                    }
                }
                sign = -sign;
            }
            ans = Math.min(ans, operations);
        }

        System.out.println(ans);
        sc.close();
    }
}

