        for (int start = 0; start < 2; start++) {
            // start=0: S[1]>0, start=1: S[1]<0
            long cost = 0;
            long prev = 0;
            for (int i = 1; i <= n; i++) {
                long T = prev + a[i];
                long Si;
                boolean wantPos = ((i + start) % 2 == 1);
                if (wantPos) { Si = Math.max(1L, T); }
                else { Si = Math.min(-1L, T); }
                cost += Math.abs(Si - T);
                prev = Si;
            }
            ans = Math.min(ans, cost);
        }
        System.out.println(ans);
    }
}

