public class Main {
    static long solve(long[] a, int startSign) {
        long ops = 0;
        long sum = 0;
        int expected = startSign; // 1 for positive, -1 for negative

        for (long x : a) {
            sum += x;
            if (expected > 0) {
                if (sum <= 0) {
                    ops += 1 - sum;
                    sum = 1;
                }
            } else {
                if (sum >= 0) {
                    ops += sum + 1;
                    sum = -1;
                }
            }
            expected *= -1;
        }
        return ops;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int n = fs.nextInt();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = fs.nextLong();

        long ans = Math.min(solve(a, 1), solve(a, -1));
        System.out.println(ans);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

