def calc(a, first_positive):
    ops = 0
    s = 0
    for i, x in enumerate(a):
        s += x
        # Required sign of prefix sum at position i
        want_positive = first_positive if i % 2 == 0 else not first_positive
        if want_positive:
            if s <= 0:
                ops += 1 - s
                s = 1
        else:
            if s >= 0:
                ops += s + 1
                s = -1
    return ops

